/bin/bash -lc "python - <<'PY'
from pathlib import Path
p=Path('Task.v');s=p.read_text()
s=s.replace('scoped 0 (open_tm_wrt_tm ?b (a_Var_f x)) |- scoped 1 ?t =>\\n    apply (@cofinite_scoped L t); intros; apply (H _ ltac:(assumption))', '''scoped 0 (open_tm_wrt_tm ?b (a_Var_f x)) |- scoped 1 ?t =>
    apply (@cofinite_scoped L t); intros y Fy;
    first [exact (proj1 (H y Fy)) | exact (proj2 (H y Fy))]''')
