/bin/bash -lc "python - <<'PY'
from pathlib import Path
p=Path('Task.v');s=p.read_text();i=s.index('Lemma intro_generation');j=s.index('Lemma pi_beta_preservation',i);t=s[i:j]
import re
t=re.sub(r'repeat split; auto;\\n      eauto using (.*)formed_refl\\.',r'''repeat split; auto;
      try solve [eauto using \\1formed_refl];
      try apply formed_refl; unfold formed; eauto.''',t)
s=s[:i]+t+s[j:];p.write_text(s)
PY
/tmp/ddc-check-tail > /tmp/ddc-tail-log 2>&1; tail -26 /tmp/ddc-tail-log"

